 env=os.environ.copy();env['CARGO_TARGET_DIR']=str(HERE/'packet-tests/target');r=subprocess.run(['cargo','+stable','test','--offline','--manifest-path',str(out/'Cargo.toml')],cwd=ROOT,env=env,capture_output=True,text=True,encoding='utf8',errors='replace');(out/'test.log').write_text(r.stdout+r.stderr,encoding='utf8')
 files=runpy.run_path(str(HERE/'particles-patch.py'))['FILES'];textures={name:hashlib.sha256((ROOT/f'upstream/LiquidBounce/src/main/resources/resources/liquidbounce/particles/{name}.png').read_bytes()).hexdigest()for name in files}
 report={'passed':r.returncode==0 and error is None,'compileExit':r.returncode,'patchError':error,'metadata':metadata,'patchedFiles':len(patched),'localeKeys':counts,'textureHashes':textures,'scope':'One focused usability invocation compiling production particles behavior, full settings serializer/parser, visual target decoder/selection, engine runtime, native Game/Host attack/camera/tick bridge and image renderer. Actual Horizon PNG decoder and quantized rotation direction. Declaration-only world/entity/actor providers. One GPU check of all eleven immutable PNG uploads and real scene depth occlusion, no effect matrix. Shared/native integration composed in memory. Actual game validation remains aggregate/root-owned.'}
